import java.util.Scanner;

public class Main {
    static final long MODUL = 1000000007;

    static int fastExponentiation(int base, int exp) {
        if (exp == 1) return base;
        int half_exp = fastExponentiation(base, exp / 2);
        long res = (1L * half_exp * half_exp) % MODUL;
        if (exp % 2 == 0) return (int) res;
        return (int) ((res * base) % MODUL);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(fastExponentiation(p, p - 1));
            return;
        }

        if (k == 1) {
            System.out.println(fastExponentiation(p, p));
            return;
        }

        int count_m = 1;
        int t_value = k;
        while (true) {
            count_m++;
            t_value = (int) ((1L * t_value * k) % p);
            if (t_value == 1) {
                System.out.println(fastExponentiation(p, (p - 1) / count_m));
                return;
            }
        }
    }
}
